// Parse AI response and structure data
const aiResponse = $json.message.content;
let analysisData;

try {
  // Extract JSON from response
  const jsonMatch = aiResponse.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    analysisData = JSON.parse(jsonMatch[0]);
  } else {
    throw new Error('No JSON found');
  }
} catch (e) {
  // Fallback structure
  analysisData = {
    ats_score: 0,
    error: 'Failed to parse AI response',
    raw_response: aiResponse
  };
}

// Add metadata
analysisData.analyzed_at = new Date().toISOString();
analysisData.role = $json.body.target_role;
analysisData.source = 'ai_powered';

return {
  json: analysisData
};
